import React, { useState } from 'react';
import { Image, View } from 'react-native';
import { MaterialCommunityIcons } from '@expo/vector-icons';

const ROBOT_ICON_URI = 'data:image/png;base64,' + '';

function ChatbotIcon({ size = 48, style, resizeMode = 'contain' }) {
  const [loadError, setLoadError] = useState(false);

  if (loadError) {
    return (
      <View style={[{ width: size, height: size, justifyContent: 'center', alignItems: 'center' }, style]}>
        <MaterialCommunityIcons name="robot" size={Math.round(size * 0.85)} color="#38BDF8" />
      </View>
    );
  }

  return (
    <Image
      source={{ uri: ROBOT_ICON_URI }}
      onError={() => setLoadError(true)}
      style={[
        {
          width: size,
          height: size,
        },
        style,
      ]}
      resizeMode={resizeMode}
    />
  );
}

export default React.memo(ChatbotIcon);
